  const realFetch = globalThis.fetch;

  afterEach(() => {
    globalThis.fetch = realFetch;
  });

  test("rejects a malformed key without any request", async () => {
    let called = false;
    globalThis.fetch = (async () => {
      called = true;
      return new Response("", { status: 200 });
    }) as typeof fetch;

    const res = await checkConnectivity("bad", PROXY);
    assert.equal(called, false);
    assert.equal(res.ok, false);
    assert.equal(res.status, "invalid_key");
    assert.equal(res.httpStatus, undefined);
    assert.match(res.message, /duelagents\.com\/dashboard\/settings/);
  });

  test("reports ok on a 200 and sends a bearer token", async () => {
    const urls: string[] = [];
    let auth: string | null = null;
    globalThis.fetch = (async (url: any, init: any) => {
      urls.push(String(url));
      auth = new Headers(init.headers).get("authorization");
      return new Response("{}", { status: 200 });
    }) as typeof fetch;

    const res = await checkConnectivity(GOOD_KEY, PROXY);
    assert.equal(res.ok, true);
    assert.equal(res.status, "ok");
    assert.equal(res.httpStatus, 200);
    assert.deepEqual(urls, [PROXY + "/models"]);
    assert.equal(auth, "Bearer " + GOOD_KEY);
  });

  test("strips a trailing slash from the proxy URL", async () => {
    const urls: string[] = [];
    globalThis.fetch = (async (url: any) => {
      urls.push(String(url));
      return new Response("{}", { status: 200 });
    }) as typeof fetch;

    await checkConnectivity(GOOD_KEY, PROXY + "/");
    assert.deepEqual(urls, [PROXY + "/models"]);
  });

  test("reports unauthorized on 401 and stops probing", async () => {
    let calls = 0;
    globalThis.fetch = (async () => {
      calls += 1;
      return new Response("", { status: 401 });
    }) as typeof fetch;

    const res = await checkConnectivity(GOOD_KEY, PROXY);
    assert.equal(calls, 1);
    assert.equal(res.ok, false);
    assert.equal(res.status, "unauthorized");
    assert.equal(res.httpStatus, 401);
  });

  test("reports unauthorized on 403", async () => {
    globalThis.fetch = (async () =>
      new Response("", { status: 403 })) as typeof fetch;
    const res = await checkConnectivity(GOOD_KEY, PROXY);
    assert.equal(res.status, "unauthorized");
    assert.equal(res.httpStatus, 403);
  });

  test("falls through to the next endpoint on a non-ok status", async () => {
    const seen: Array<{ url: string; method: string }> = [];
    globalThis.fetch = (async (url: any, init: any) => {
