describe("getProxyUrl", () => {
  const saved = {
    DUEL_PROXY_URL: process.env.DUEL_PROXY_URL,
    NEXT_PUBLIC_PROXY_URL: process.env.NEXT_PUBLIC_PROXY_URL,
  };

  beforeEach(() => {
    delete process.env.DUEL_PROXY_URL;
    delete process.env.NEXT_PUBLIC_PROXY_URL;
  });

  afterEach(() => {
    for (const [k, v] of Object.entries(saved)) {
      if (v === undefined) delete process.env[k];
      else process.env[k] = v;
    }
  });

  test("falls back to the default", () => {
    assert.equal(getProxyUrl(), DEFAULT_PROXY_URL);
  });

  test("prefers DUEL_PROXY_URL", () => {
    process.env.DUEL_PROXY_URL = "https://a.example/v1";
    process.env.NEXT_PUBLIC_PROXY_URL = "https://b.example/v1";
    assert.equal(getProxyUrl(), "https://a.example/v1");
  });

  test("falls back to NEXT_PUBLIC_PROXY_URL", () => {
    process.env.NEXT_PUBLIC_PROXY_URL = "https://b.example/v1";
    assert.equal(getProxyUrl(), "https://b.example/v1");
  });

  test("trims whitespace and strips a trailing slash", () => {
    process.env.DUEL_PROXY_URL = "  https://a.example/v1/  ";
    assert.equal(getProxyUrl(), "https://a.example/v1");
  });

  test("ignores a blank value and uses the next source", () => {
    process.env.DUEL_PROXY_URL = "   ";
    process.env.NEXT_PUBLIC_PROXY_URL = "http://b.example";
    assert.equal(getProxyUrl(), "http://b.example");
  });

  test("ignores blank values entirely", () => {
    process.env.DUEL_PROXY_URL = "";
    process.env.NEXT_PUBLIC_PROXY_URL = "  ";
    assert.equal(getProxyUrl(), DEFAULT_PROXY_URL);
  });

  test("accepts http and is case insensitive on the scheme", () => {
    process.env.DUEL_PROXY_URL = "HTTP://a.example/v1";
    assert.equal(getProxyUrl(), "HTTP://a.example/v1");
  });

  test("throws on a non http(s) URL", () => {
    process.env.DUEL_PROXY_URL = "ftp://a.example";
    assert.throws(() => getProxyUrl(), /Invalid DUEL_PROXY_URL/);
    process.env.DUEL_PROXY_URL = "a.example";
    assert.throws(() => getProxyUrl(), /Invalid DUEL_PROXY_URL/);
