    const expected = { DUEL_API_KEY: GOOD_KEY, DUEL_PROXY_URL: PROXY };
    assert.deepEqual(getEnvForTarget("cursor", GOOD_KEY, PROXY), expected);
    assert.deepEqual(getEnvForTarget("openclaw", GOOD_KEY, PROXY), expected);
  });

  test("unknown targets fall back to the Duel variables", () => {
    assert.deepEqual(getEnvForTarget("mystery" as InstallTarget, GOOD_KEY, PROXY), {
      DUEL_API_KEY: GOOD_KEY,
      DUEL_PROXY_URL: PROXY,
    });
  });

  test("validates the key first", () => {
    assert.throws(
      () => getEnvForTarget("claude-code", "bad", PROXY),
      /Invalid or missing DUEL_API_KEY/,
    );
