      assert.equal(vars.ANTHROPIC_BASE_URL, DEFAULT_PROXY_URL);
    } finally {
      if (saved === undefined) delete process.env.DUEL_PROXY_URL;
      else process.env.DUEL_PROXY_URL = saved;
    }
  });
});
