    assert.equal(patch.models.providers.duel.apiKey, "${DUEL_API_KEY}");
  });

  test("shapes the provider block", () => {
    const patch = buildOpenClawPatch(GOOD_KEY, PROXY) as any;
    assert.equal(patch.models.mode, "merge");
    const duel = patch.models.providers.duel;
    assert.equal(duel.baseUrl, PROXY);
    assert.equal(duel.api, "openai-completions");
    assert.equal(duel.models.length, 1);
    assert.deepEqual(duel.models[0], {
      id: "duel-auto",
      name: "Duel Auto",
      reasoning: false,
      input: ["text"],
      cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 },
      contextWindow: 200000,
      maxTokens: 8192,
    });
  });

  test("sets the default agent model and alias", () => {
    const patch = buildOpenClawPatch(GOOD_KEY, PROXY) as any;
    assert.deepEqual(patch.agents.defaults.model, { primary: "duel/duel-auto" });
    assert.deepEqual(patch.agents.defaults.models, {
      "duel/duel-auto": { alias: "Duel" },
    });
  });

  test("puts only the proxy URL in env", () => {
    const patch = buildOpenClawPatch(GOOD_KEY, PROXY) as any;
    assert.deepEqual(patch.env, { DUEL_PROXY_URL: PROXY });
  });

  test("validates the key", () => {
    assert.throws(
      () => buildOpenClawPatch("bad", PROXY),
      /Invalid or missing DUEL_API_KEY/,
    );
  });
});

describe("deepMerge", () => {
  test("merges nested plain objects", () => {
    const base = { a: { b: 1, c: 2 }, d: 3 };
    const patch = { a: { c: 9, e: 4 } };
    assert.deepEqual(deepMerge(base, patch), { a: { b: 1, c: 9, e: 4 }, d: 3 });
  });

  test("replaces arrays instead of concatenating", () => {
    assert.deepEqual(deepMerge({ a: [1, 2, 3] }, { a: [9] }), { a: [9] });
    assert.deepEqual(deepMerge({ a: { b: 1 } }, { a: [9] }), { a: [9] });
    assert.deepEqual(deepMerge({ a: [1] }, { a: { b: 1 } }), { a: { b: 1 } });
  });

  test("replaces scalars and null", () => {
    assert.deepEqual(deepMerge({ a: 1 }, { a: "x" }), { a: "x" });
    assert.deepEqual(deepMerge({ a: { b: 1 } }, { a: null }), { a: null });
    assert.deepEqual(deepMerge({ a: null }, { a: { b: 1 } }), { a: { b: 1 } });
  });

  test("keeps base keys that the patch does not mention", () => {
    assert.deepEqual(deepMerge({ a: 1, b: 2 }, { b: 3 }), { a: 1, b: 3 });
  });

  test("does not mutate its inputs", () => {
    const base = { a: { b: 1 } };
    const patch = { a: { c: 2 } };
    const out = deepMerge(base, patch);
    assert.deepEqual(base, { a: { b: 1 } });
    assert.deepEqual(patch, { a: { c: 2 } });
    assert.notEqual(out, base as unknown);
    assert.notEqual((out as any).a, (base as any).a);
  });

  test("handles empty inputs", () => {
    assert.deepEqual(deepMerge({}, {}), {});
    assert.deepEqual(deepMerge({ a: 1 }, {}), { a: 1 });
    assert.deepEqual(deepMerge({}, { a: 1 }), { a: 1 });
  });
});
